// M5 fixed driver for sources.psf.
//
// Positive fit: the synthetic 9x9 frame is generated by the same pixel-integral
// model as the fitter (evaluate_psf of a frozen EffectivePSF with sigma=1.2),
// so the exact model is inside the family and fit_psf converges to the injected
// width with a certified parameter interval.
//
// Retained failure attempt: a frame generated by point-sampling the Gaussian at
// pixel centres (instead of integrating over the pixel) is outside the model
// family; the same fitter reports the named nonconverged result.  It is kept as
// evidence and never counted as a pass.
//
// evaluate_psf and bind_observation_model run on the fitted kernel.
#include "../lib/fixtures.hpp"

#include <acsd/modules/coordinates.hpp>
#include <acsd/modules/sources.hpp>

#include <array>
#include <cmath>
#include <memory>
#include <numeric>
#include <string>
#include <vector>

namespace {

using namespace acsd;
using namespace acsd::rt;

constexpr double kDegToRad = 3.14159265358979323846 / 180.0;
constexpr double kTrueSigma = 1.2;
constexpr double kInjectedFlux = 100.0;

Ref<Response> make_response(const rt::InvocationContext& ctx, const Ref<Index>& index) {
  auto response = std::make_shared<Response>();
  auto wavelength = vpf::make_array<double>(ctx, DType::f64, {450, 500, 550, 600, 650}, {5},
                                            index, vpf::unit_of("nm"));
  auto throughput = vpf::make_array<double>(ctx, DType::f64, {1, 1, 1, 1, 1}, {5}, index,
                                            vpf::dimensionless());
  if (wavelength.code != Code::ok || throughput.code != Code::ok) return {};
  response->wavelength_nm = wavelength.value->array;
  response->throughput = throughput.value->array;
  response->convention = Response::Convention::photon_throughput;
  response->support_nm = Interval{450.0, 650.0};
  response->identity = vpf::identity_of("response:flat", "acsd.Response");
  response->assessment.complete = true;
  return response;
}

Ref<EffectivePSF> make_kernel(const rt::InvocationContext& ctx, const Ref<Index>& index,
                              const Ref<FootprintSet>& footprints) {
  auto parameters = vpf::make_array<double>(ctx, DType::f64,
                                            {std::log(kTrueSigma), std::log(kTrueSigma), 0.0},
                                            {3}, index, vpf::dimensionless());
  if (parameters.code != Code::ok) return {};
  auto kernel = std::make_shared<EffectivePSF>();
  kernel->family = PsfRequest::Family::gaussian;
  kernel->parameters = parameters.value->array;
  kernel->spatial_domain = Box{Vec2{-0.5, -0.5}, Vec2{8.5, 8.5}};
  kernel->wavelength_nm = Interval{450.0, 650.0};
  kernel->tail_mass_upper = 0.0;
  kernel->spatial_basis.kind = Basis::Kind::constant;
  kernel->spatial_basis.degree = 0;
  kernel->achromatic = true;
  kernel->detector_samples = footprints;
  kernel->frame = "frame0";
  kernel->identity = vpf::identity_of("psf:validation", "acsd.EffectivePSF");
  kernel->assessment.complete = true;
  return kernel;
}

bool close(double a, double b, double tolerance) { return std::fabs(a - b) <= tolerance; }

}  // namespace

int main() {
  vrt::Recorder recorder("sources.psf", "validation/process/sources.psf/psf.cpp");
  auto started = vpf::start({{"coordinates.wcs", &acsd::modules::register_wcs},
                             {"sources.psf", &acsd::modules::register_psf}},
                            1ull << 30, 128000000);
  for (const auto& [name, code] : started.steps)
    recorder.check("start." + name, code == Code::ok, "ok", vrt::code_name(code));
  if (started.chain.code != Code::ok || !started.chain.value) return recorder.finish();
  const vpf::Chain& chain = *started.chain.value;

  HeaderFields header;
  auto text = [&header](const char* key, const std::string& value) {
    HeaderField field;
    field.key = key;
    field.value = value;
    header.push_back(std::move(field));
  };
  auto number = [&header](const char* key, double value) {
    HeaderField field;
    field.key = key;
    field.value = value;
    header.push_back(std::move(field));
  };
  text("CTYPE1", "RA---TAN");
  text("CTYPE2", "DEC--TAN");
  text("RADESYS", "ICRS");
  number("CRPIX1", 5.0);
  number("CRPIX2", 5.0);
  number("CRVAL1", 10.0);
  number("CRVAL2", 20.0);
  number("CD1_1", -0.001);
  number("CD2_2", 0.001);
  auto make_input = std::make_shared<modules::MakeWcsInput>();
  make_input->header = header;
  make_input->domain = Box{Vec2{-0.5, -0.5}, Vec2{8.5, 8.5}};
  make_input->detector_frame = "detector0";
  make_input->request = vpf::budget(1e-12, 1e-12, 128);
  auto wcs = vpf::invoke<modules::MakeWcsInput, Ref<WcsModel>>(chain, "coordinates.wcs",
                                                               "make_wcs", make_input);
  recorder.expect_code("fixture.wcs", "ok", wcs);
  if (wcs.code != Code::ok || !wcs.value) return recorder.finish();

  const auto index = vpf::make_index(81, "native:frame0");
  const auto footprints = vpf::make_footprints(index, 9, 9, "detector0");
  const Ref<EffectivePSF> kernel_fixture = make_kernel(chain.command, index, footprints);
  recorder.check("fixture.kernel", kernel_fixture != nullptr, "true",
                 kernel_fixture ? "true" : "false");
  if (!kernel_fixture) return recorder.finish();
  const std::vector<CatalogueStar> stars{
      vpf::make_star(7, 10.0 * kDegToRad, 20.0 * kDegToRad, 2016.0)};

  // ---- positive: image generated by the pixel-integral model -------------
  auto evaluate_fixture = std::make_shared<modules::EvaluatePsfInput>();
  evaluate_fixture->psf = kernel_fixture;
  evaluate_fixture->request.source_positions = {PixelCenter0{4.0, 4.0}};
  evaluate_fixture->request.budget = vpf::budget(1e-12, 1e-12, 128);
  auto template_values = vpf::invoke<modules::EvaluatePsfInput, Ref<PsfEvaluation>>(
      chain, "sources.psf", "evaluate_psf", evaluate_fixture);
  recorder.expect_code("fixture.pixel_integral_template", "ok", template_values);
  if (template_values.code != Code::ok || !template_values.value) return recorder.finish();
  std::vector<double> profile =
      vpf::read_f64(chain.command, (*template_values.value)->values, 81);
  const double profile_sum =
      std::accumulate(profile.begin(), profile.end(), 0.0);
  recorder.check("fixture.pixel_integral_sum", profile.size() == 81 && profile_sum > 0.0,
                 "81 positive samples", std::to_string(profile.size()));
  if (profile.size() != 81 || !(profile_sum > 0.0)) return recorder.finish();
  std::vector<double> integrated_image(81);
  for (std::size_t i = 0; i < profile.size(); ++i)
    integrated_image[i] = kInjectedFlux * profile[i] / profile_sum;
  const Ref<NativeObservation> integrated_native = vpf::make_native_with(
      chain.command, integrated_image, std::vector<std::uint16_t>(81, 0), index, footprints,
      "frame0", 2016.0);
  recorder.check("fixture.integrated_native", integrated_native != nullptr, "true",
                 integrated_native ? "true" : "false");
  if (!integrated_native) return recorder.finish();

  auto fit_input = std::make_shared<modules::FitPsfInput>();
  fit_input->observation = integrated_native;
  fit_input->wcs = *wcs.value;
  fit_input->stars = std::make_shared<const std::vector<CatalogueStar>>(stars);
  fit_input->request.family = PsfRequest::Family::gaussian;
  fit_input->request.spatial_degree = 0;
  fit_input->request.initial_width_pixel = kTrueSigma;
  fit_input->request.tail_absolute_flux = 0.0;
  fit_input->request.window_radius_pixel = 3.0;
  fit_input->request.budget = vpf::budget(1e-8, 1e-10, 512);
  auto fit_plan = modules::plan_fit_psf_op(chain.command, fit_input,
                                           PlanOptions{1, 1, Placement::memory});
  recorder.expect_code("fit.plan", "ok", fit_plan);
  if (fit_plan.code == Code::ok) {
    recorder.value("fit.plan.elements", fit_plan.value->elements);
    recorder.value("fit.plan.persistent_host_bytes", fit_plan.value->persistent.host_bytes);
    recorder.value("fit.plan.progress_floor_host_bytes", fit_plan.value->progress_floor.host_bytes);
  }
  auto fitted = vpf::invoke<modules::FitPsfInput, Ref<EffectivePSF>>(
      chain, "sources.psf", "fit_psf", fit_input);
  recorder.expect_code("fit.run", "ok", fitted);
  if (fitted.code == Code::ok && fitted.value) {
    const EffectivePSF& psf = **fitted.value;
    std::vector<double> parameters = vpf::read_f64(chain.command, psf.parameters, 3);
    const std::vector<double> lower = vpf::read_f64(chain.command, psf.parameter_lower, 3);
    const std::vector<double> upper = vpf::read_f64(chain.command, psf.parameter_upper, 3);
    recorder.check("fit.parameters_present",
                   parameters.size() == 3 && lower.size() == 3 && upper.size() == 3, "3/3/3",
                   std::to_string(parameters.size()) + "/" + std::to_string(lower.size()) + "/" +
                       std::to_string(upper.size()));
    if (parameters.size() == 3) {
      const double fitted_sigma = std::exp(parameters[0]);
      recorder.value("fit.sigma", fitted_sigma);
      recorder.check("fit.sigma_recovers_injection", close(fitted_sigma, kTrueSigma, 1e-3),
                     vrt::number(kTrueSigma), vrt::number(fitted_sigma));
      if (lower.size() == 3 && upper.size() == 3) {
        recorder.check("fit.parameter_interval_brackets",
                       lower[0] <= parameters[0] && parameters[0] <= upper[0], "lower<=p<=upper",
                       vrt::number(lower[0]) + "<=" + vrt::number(parameters[0]) + "<=" +
                           vrt::number(upper[0]));
        recorder.value("fit.sigma_lower", std::exp(lower[0]));
        recorder.value("fit.sigma_upper", std::exp(upper[0]));
      }
    }
    recorder.check("fit.assessment_complete", psf.assessment.complete, "true",
                   psf.assessment.complete ? "true" : "false");

    // evaluate on the fitted kernel.
    auto evaluate_input = std::make_shared<modules::EvaluatePsfInput>();
    evaluate_input->psf = *fitted.value;
    evaluate_input->request.source_positions = {PixelCenter0{4.0, 4.0}};
    evaluate_input->request.budget = vpf::budget(1e-8, 1e-10, 256);
    auto evaluate_plan = modules::plan_evaluate_psf_op(chain.command, evaluate_input,
                                                       PlanOptions{1, 1, Placement::memory});
    recorder.expect_code("evaluate.plan", "ok", evaluate_plan);
    if (evaluate_plan.code == Code::ok) {
      recorder.value("evaluate.plan.elements", evaluate_plan.value->elements);
      recorder.value("evaluate.plan.persistent_host_bytes",
                     evaluate_plan.value->persistent.host_bytes);
      recorder.value("evaluate.plan.progress_floor_host_bytes",
                     evaluate_plan.value->progress_floor.host_bytes);
    }
    auto evaluation = vpf::invoke<modules::EvaluatePsfInput, Ref<PsfEvaluation>>(
        chain, "sources.psf", "evaluate_psf", evaluate_input);
    recorder.expect_code("evaluate.run", "ok", evaluation);

    // bind the fitted kernel and a flat response to the observation.
    auto response_index = vpf::make_index(5, "response");
    const Ref<Response> response = make_response(chain.command, response_index);
    recorder.check("fixture.response", response != nullptr, "true",
                   response ? "true" : "false");
    if (response) {
      auto bind_input = std::make_shared<modules::BindObservationModelInput>();
      bind_input->observation = integrated_native;
      bind_input->kernel = *fitted.value;
      bind_input->response = response;
      auto bind_plan = modules::plan_bind_observation_model_op(
          chain.command, bind_input, PlanOptions{1, 1, Placement::memory});
      recorder.expect_code("bind.plan", "ok", bind_plan);
      auto bound = vpf::invoke<modules::BindObservationModelInput, Ref<NativeObservation>>(
          chain, "sources.psf", "bind_observation_model", bind_input);
      recorder.expect_code("bind.run", "ok", bound);
      if (bound.code == Code::ok)
        recorder.check("bind.kernel", (*bound.value)->kernel != nullptr, "true",
                       (*bound.value)->kernel ? "true" : "false");
    }
  }

  // ---- retained failure attempt: point-sampled frame --------------------
  const Ref<NativeObservation> point_native = vpf::make_native_with(
      chain.command,
      vpf::gaussian_image(9, 9, {std::array<double, 3>{4.0, 4.0, kInjectedFlux}}, kTrueSigma,
                          0.0),
      std::vector<std::uint16_t>(81, 0), index, footprints, "frame0", 2016.0);
  if (point_native) {
    auto point_input = std::make_shared<modules::FitPsfInput>(*fit_input);
    point_input->observation = point_native;
    auto point = vpf::invoke<modules::FitPsfInput, Ref<EffectivePSF>>(
        chain, "sources.psf", "fit_psf", point_input);
    recorder.expect_code("attempt.point_sampled_nonconverged", "nonconverged", point);
    recorder.check("attempt.point_sampled_no_value", !point.value.has_value(), "no value",
                   point.value.has_value() ? "value produced" : "no value");
    // A looser score tolerance shows whether the remaining gap is the model
    // family (point sampling versus pixel integration) or pure precision.
    auto loose_input = std::make_shared<modules::FitPsfInput>(*point_input);
    loose_input->request.budget = vpf::budget(1e-4, 1e-10, 512);
    auto loose = vpf::invoke<modules::FitPsfInput, Ref<EffectivePSF>>(
        chain, "sources.psf", "fit_psf", loose_input);
    recorder.value("attempt.point_sampled_loose_code", vrt::code_name(loose.code));
    recorder.check("attempt.point_sampled_loose_named",
                   loose.code == Code::ok || loose.code == Code::nonconverged,
                   "ok or nonconverged", vrt::code_name(loose.code));
  }

  // ---- negative: spatial degree three is outside the contract -----------
  auto bad_input = std::make_shared<modules::FitPsfInput>(*fit_input);
  bad_input->request.spatial_degree = 3;
  auto bad = vpf::invoke<modules::FitPsfInput, Ref<EffectivePSF>>(
      chain, "sources.psf", "fit_psf", bad_input);
  recorder.expect_code("negative.spatial_degree", "invalid_request", bad);

  return recorder.finish();
}
